    const cur = goal && goal.kind === 'zoom' ? goal : { kind: 'zoom', r: sph.r, t: target.clone() };
    const r1 = THREE.MathUtils.clamp(cur.r * k, 60, 400000);
    const p = groundPoint(e.clientX, e.clientY, target.z);
