  function flyTo(t, r, phi, theta, ms = 1800) { goal = { kind: 'fly', t0: performance.now(), ms, a: { t: target.clone(), r: sph.r, phi: sph.phi, theta: sph.theta }, b: { t, r, phi: phi ?? sph.phi, theta: theta ?? sph.theta } }; }
